#pragma once

#include <stdbool.h>
#include <stdint.h>

#include "tide/entity.h"
#include "tide/math.h"

// Random numbers whose state is data: Tide's Random. Code generated by tidec
// depends on these functions.
//
// A generator is 8 bytes of state, which live wherever the game puts them: a
// component, a singleton, a local. Each number steps the state, so a world's
// generators are in its snapshots and its hash like any other field, and a
// tick run again draws the same numbers.
//
// Everything here is integer arithmetic, and floats made from integers with
// exact operations (a conversion of 24 bits and a multiplication by a power
// of two), so every platform gives the same bits. The directions go through
// tide/math.h's sin and cos, which do too.
//
// The generator is PCG-XSH-RR 64/32 (O'Neill): a 64-bit linear congruential
// state, and 32 bits of it out each step, rotated by its top bits. Any state
// works, zero included, and the sequence comes back after 2^64 numbers.
//
// Code the GPU runs (a frag or a vert that rolls) has no 64-bit integers, so it
// rolls with a 32-bit generator of the compiler's own. What it makes of each
// 32 bits is what these functions make of theirs: its ranges and its floats
// follow the formulas here.

typedef struct tide_random {
    int64_t state;
} tide_random;

// SplitMix64's finalizer: every bit of the result depends on every bit given.
static inline uint64_t tide_random_mix(uint64_t z)
{
    z = (z ^ (z >> 30)) * 0xBF58476D1CE4E5B9ull;
    z = (z ^ (z >> 27)) * 0x94D049BB133111EBull;
    return z ^ (z >> 31);
}

#define TIDE_RANDOM_GOLDEN 0x9E3779B97F4A7C15ull

// Random(seed): a generator for the seed. Seeds next to each other (1, 2, 3)
// give sequences that have nothing to do with each other. Never state zero,
// which is a generator nothing seeded yet (tide_random_place).
static inline tide_random tide_random_seeded(const int64_t seed)
{
    const uint64_t state = tide_random_mix((uint64_t)seed + TIDE_RANDOM_GOLDEN);
    return (tide_random){(int64_t)(state ? state : TIDE_RANDOM_GOLDEN)};
}

// The generator of a field nothing seeded, which the engine seeds: from the
// match's seed, the tick, the entity it's spawned on (or added to) and which
// of the entity's fields it is, so no two are alike and a tick run again
// gives the same. The null entity is a singleton's.
static inline tide_random tide_random_place(const uint32_t seed, const uint32_t tick, const tide_entity entity, const uint32_t place)
{
    uint64_t state = tide_random_mix((((uint64_t)seed << 32) | tick) + TIDE_RANDOM_GOLDEN);
    state = tide_random_mix(state ^ (((uint64_t)entity.generation << 32) | entity.index));
    state = tide_random_mix(state + ((uint64_t)place + 1u) * TIDE_RANDOM_GOLDEN);
    return (tide_random){(int64_t)(state ? state : TIDE_RANDOM_GOLDEN)};
}

// Seeds a field in place when nothing has: a state of zero.
static inline void tide_random_seed_place(tide_random *r, const uint32_t seed, const uint32_t tick, const tide_entity entity,
                                          const uint32_t place)
{
    if (r->state == 0) *r = tide_random_place(seed, tick, entity, place);
}

// The next 32 bits.
static inline uint32_t tide_random_next(tide_random *r)
{
    const uint64_t state = (uint64_t)r->state * 6364136223846793005ull + 1442695040888963407ull;
    r->state = (int64_t)state;
    const uint32_t mixed = (uint32_t)(((state >> 18) ^ state) >> 27);
    const uint32_t turn = (uint32_t)(state >> 59);
    return (mixed >> turn) | (mixed << ((32u - turn) & 31u));
}

// A generator of its own for something a generator's code starts: a task, or a
// loop whose steps run at once. It steps `r` twice, and what it gives has
// nothing to do with what `r` rolls next.
static inline tide_random tide_random_fork(tide_random *r)
{
    const uint64_t high = tide_random_next(r);
    const uint64_t low = tide_random_next(r);
    return (tide_random){(int64_t)tide_random_mix((high << 32) | low)};
}

// One of those for each step of such a loop, from the loop's and the step's
// place: a grid's cell or a list's index, whichever thread runs it.
static inline tide_random tide_random_step(const tide_random loop, const int32_t x, const int32_t y, const int32_t z)
{
    uint64_t state = tide_random_mix((uint64_t)loop.state ^ (((uint64_t)(uint32_t)x << 32) | (uint32_t)y));
    state = tide_random_mix(state + ((uint64_t)(uint32_t)z + 1u) * TIDE_RANDOM_GOLDEN);
    return (tide_random){(int64_t)state};
}

// NextInt(): from 0 to 2147483647, like Math.Hash, so % never goes negative.
static inline int32_t tide_random_next_int(tide_random *r)
{
    return (int32_t)(tide_random_next(r) >> 1);
}

// NextInt(min, max): from min up to max, max excluded; min when there's
// nothing between them. The 32 bits scaled down to the range (Lemire's
// multiply and shift), as Unity.Mathematics does.
static inline int32_t tide_random_next_int_between(tide_random *r, const int32_t min, const int32_t max)
{
    const uint32_t bits = tide_random_next(r);
    if (max <= min) return min;
    const uint32_t range = (uint32_t)max - (uint32_t)min;
    return (int32_t)((uint32_t)min + (uint32_t)(((uint64_t)bits * range) >> 32));
}

// NextInt(max): from 0 up to max, max excluded.
static inline int32_t tide_random_next_int_below(tide_random *r, const int32_t max)
{
    return tide_random_next_int_between(r, 0, max);
}

// NextFloat(): from 0 up to 1, 1 excluded: 24 random bits over 2^24, which a
// float holds exactly.
static inline float tide_random_next_float(tide_random *r)
{
    return (float)(tide_random_next(r) >> 8) * (1.0f / 16777216.0f);
}

// NextFloat(min, max): from min up to max, max excluded; min when there's
// nothing between them, or when rounding would give max.
static inline float tide_random_next_float_between(tide_random *r, const float min, const float max)
{
    const float value = min + (max - min) * tide_random_next_float(r);
    return value < max ? value : min;
}

// NextFloat(max): from 0 up to max, max excluded.
static inline float tide_random_next_float_below(tide_random *r, const float max)
{
    return tide_random_next_float_between(r, 0.0f, max);
}

// NextBool()
static inline bool tide_random_next_bool(tide_random *r)
{
    return (tide_random_next(r) >> 31) != 0;
}

// NextFloat2() and NextFloat3(): each component from 0 up to 1, x first.
static inline tide_float2 tide_random_next_float2(tide_random *r)
{
    const float x = tide_random_next_float(r);
    const float y = tide_random_next_float(r);
    return (tide_float2){x, y};
}

static inline tide_float3 tide_random_next_float3(tide_random *r)
{
    const float x = tide_random_next_float(r);
    const float y = tide_random_next_float(r);
    const float z = tide_random_next_float(r);
    return (tide_float3){x, y, z};
}

// NextFloat2(min, max) and NextFloat3(min, max): each component between its own two.
static inline tide_float2 tide_random_next_float2_between(tide_random *r, const tide_float2 min, const tide_float2 max)
{
    const float x = tide_random_next_float_between(r, min.x, max.x);
    const float y = tide_random_next_float_between(r, min.y, max.y);
    return (tide_float2){x, y};
}

static inline tide_float3 tide_random_next_float3_between(tide_random *r, const tide_float3 min, const tide_float3 max)
{
    const float x = tide_random_next_float_between(r, min.x, max.x);
    const float y = tide_random_next_float_between(r, min.y, max.y);
    const float z = tide_random_next_float_between(r, min.z, max.z);
    return (tide_float3){x, y, z};
}

// NextFloat2Direction(): a point on the unit circle, every angle as likely.
static inline tide_float2 tide_random_next_float2_direction(tide_random *r)
{
    const float angle = tide_random_next_float(r) * TIDE_TAU_F;
    return (tide_float2){tide_cos_f(angle), tide_sin_f(angle)};
}

// NextFloat3Direction(): a point on the unit sphere, every direction as likely.
static inline tide_float3 tide_random_next_float3_direction(tide_random *r)
{
    const float z = tide_random_next_float(r) * 2.0f - 1.0f;
    const float angle = tide_random_next_float(r) * TIDE_TAU_F;
    const float radius = tide_sqrt_f(tide_max_f(1.0f - z * z, 0.0f));
    return (tide_float3){tide_cos_f(angle) * radius, tide_sin_f(angle) * radius, z};
}

// NextQuaternionRotation(): a rotation, every one as likely, with w never negative.
static inline tide_quaternion tide_random_next_quaternion_rotation(tide_random *r)
{
    const float theta = tide_random_next_float(r) * TIDE_TAU_F;
    const float rho = tide_random_next_float(r) * TIDE_TAU_F;
    const float u = tide_random_next_float(r);
    const float i = tide_sqrt_f(1.0f - u);
    const float j = tide_sqrt_f(u);
    tide_float4 q = {i * tide_sin_f(theta), i * tide_cos_f(theta), j * tide_sin_f(rho), j * tide_cos_f(rho)};
    if (q.w < 0.0f) q = (tide_float4){-q.x, -q.y, -q.z, -q.w};
    return (tide_quaternion){q};
}
